CREATE COLUMN TABLE "TEST_AP"."ODRN" ("DocEntry" INTEGER CS_INT NOT NULL , "DocNum" INTEGER CS_INT, "Series" INTEGER CS_INT, "DprArea" NVARCHAR(15), "Status" NVARCHAR(1) DEFAULT 'D', "Canceled" NVARCHAR(1) DEFAULT 'N', "RefDate" LONGDATE CS_LONGDATE, "PeriodCat" NVARCHAR(10), "PostPeriod" INTEGER CS_INT, "KeyDate" LONGDATE CS_LONGDATE, "Remarks" NVARCHAR(32), "NumOfJEs" INTEGER CS_INT, "SumOfDpr" DECIMAL(21,6) CS_FIXED, "SumByPro" NVARCHAR(1) DEFAULT 'N', "SumByDistr" NVARCHAR(1) DEFAULT 'N', "TransType" NVARCHAR(20) DEFAULT '-1', "TransAbs" INTEGER CS_INT, PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE 